class RecordingLedger final : public Ledger {
 public:
  void deposit(AccountId id, Amount amount) override {
    balances_.insert_or_assign(id, balances_[id] + amount);   // behaviour
    journal_.push_back(Operation{"deposit", id, amount});     // recorded
  }
  const std::vector<Operation>& journal() const { return journal_; }  // test accessor

 private:
  std::unordered_map<AccountId, Amount> balances_;
  std::vector<Operation> journal_;
};
